-- Generated by tools/build_quest_data.py; references are not eligibility or a walkthrough.
return {["scripts/zones/The_Eldieme_Necropolis/npcs/Sarcophagus.lua"]={["Path"]="scripts/zones/The_Eldieme_Necropolis/npcs/Sarcophagus.lua",["SHA256"]="b32d47fc96ea2129d09f1425252b6f9a7c56a1835b01d7ba333e9a03b8b38df0",["Text"]="-----------------------------------\n-- Area: The Eldieme Necropolis\n--  NPC: Sarcophagus\n-- Involved in Quests: A New Dawn (BST AF3)\n-- !pos -420 8 500 195\n-----------------------------------\nlocal ID = zones[xi.zone.THE_ELDIEME_NECROPOLIS]\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrigger = function(player, npc)\n    -- A NEW DAWN (Beastmaster AF3)\n    if\n        player:getQuestStatus(xi.questLog.JEUNO, xi.quest.id.jeuno.A_NEW_DAWN) == xi.questStatus.QUEST_ACCEPTED and\n        npc:getID() == ID.npc.SARCOPHAGUS_OFFSET\n    then\n        local aNewDawnEvent = player:getCharVar('ANewDawn_Event')\n\n        if aNewDawnEvent == 4 then\n            npcUtil.popFromQM(player, npc, { ID.mob.STURM, ID.mob.TAIFUN, ID.mob.TROMBE }, { claim = false, hide = 0 })\n        elseif aNewDawnEvent == 5 then\n            player:startEvent(45)\n        end\n\n    -- DEFAULT DIALOG\n    else\n        player:messageSpecial(ID.text.SARCOPHAGUS_CANNOT_BE_OPENED)\n    end\nend\n\nentity.onEventFinish = function(player, csid, option, npc)\n    -- A NEW DAWN\n    if\n        csid == 45 and\n        npcUtil.completeQuest(player, xi.questLog.JEUNO, xi.quest.id.jeuno.A_NEW_DAWN, { item = 14222, title = xi.title.PARAGON_OF_BEASTMASTER_EXCELLENCE })\n    then\n        player:setCharVar('ANewDawn_Event', 6)\n        player:delKeyItem(xi.keyItem.TAMERS_WHISTLE)\n    end\nend\n\nreturn entity\n"},["scripts/zones/The_Eldieme_Necropolis_[S]/npcs/Heptachiond.lua"]={["Path"]="scripts/zones/The_Eldieme_Necropolis_[S]/npcs/Heptachiond.lua",["SHA256"]="937276493fd36bb3493fd41a66bce22869156bb4ff302ee6f8bb9be96a6b3e4d",["Text"]="-----------------------------------\n-- Area: The_Eldieme_Necropolis_[S]\n--  NPC: Heptachiond\n-- Starts and Finishes Quest: REQUIEM_FOR_THE_DEPARTED\n-- !pos 256 -32 20 175\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrigger = function(player, npc)\n    local rftd = player:getQuestStatus(xi.questLog.CRYSTAL_WAR, xi.quest.id.crystalWar.REQUIEM_FOR_THE_DEPARTED)\n\n    -- Change to BRASS_RIBBON_OF_SERVICE later when Campaign has been added.\n    if\n        rftd == xi.questStatus.QUEST_AVAILABLE and\n        player:hasKeyItem(xi.keyItem.BRONZE_RIBBON_OF_SERVICE) and\n        player:getMainLvl() >= 30\n    then\n        player:startEvent(105) -- Start quest \"Requiem for the Departed\"\n    elseif rftd == xi.questStatus.QUEST_ACCEPTED then\n        if player:hasKeyItem(xi.keyItem.SHEAF_OF_HANDMADE_INCENSE) then\n            player:startEvent(107) -- During quest \"Requiem for the Departed\" (with Handmade Incense KI)\n        else\n            player:startEvent(106) -- During quest \"Requiem for the Departed\" (before retrieving KI Handmade Incense)\n        end\n    elseif rftd == xi.questStatus.QUEST_COMPLETED then\n        player:startEvent(108) -- New standard dialog after \"Requiem for the Departed\"\n    else\n        player:startEvent(104) -- Standard dialog\n    end\nend\n\nentity.onEventFinish = function(player, csid, option, npc)\n    if csid == 105 then\n        player:addQuest(xi.questLog.CRYSTAL_WAR, xi.quest.id.crystalWar.REQUIEM_FOR_THE_DEPARTED)\n    elseif\n        csid == 107 and\n        npcUtil.completeQuest(player, xi.questLog.CRYSTAL_WAR, xi.quest.id.crystalWar.REQUIEM_FOR_THE_DEPARTED, { item = xi.item.SCROLL_OF_RECALL_MERIPH })\n    then\n        player:delKeyItem(xi.keyItem.SHEAF_OF_HANDMADE_INCENSE)\n    end\nend\n\nreturn entity\n"},["scripts/zones/Uleguerand_Range/npcs/qm_moblin_hotrok.lua"]={["Path"]="scripts/zones/Uleguerand_Range/npcs/qm_moblin_hotrok.lua",["SHA256"]="b345321b720934dc4df39f20a78002911c388fdf62273bc8bc63737d7ad13072",["Text"]="-----------------------------------\n-- Area: Uleguerand_Range\n--  NPC: ??? (Trade Moblin Hotrok for Map of Uleguerand Range)\n-- !pos -299 -62 -18\n-- Involved in Quests: Over The Hills And Far Away\n-----------------------------------\nlocal ID = zones[xi.zone.ULEGUERAND_RANGE]\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\n-- TODO: This logic needs to be verified, and conditions slimmed down.  Companion of Louverance is granted on completion of that path,\n-- while True Companion is granted during the Ulmia path.\n\nentity.onTrade = function(player, npc, trade)\n    local overTheHillsAndFarAway = player:getQuestStatus(xi.questLog.SANDORIA, xi.quest.id.sandoria.OVER_THE_HILLS_AND_FAR_AWAY)\n\n    -- Taking a logical guess what criteria displays what message.\n    if\n        overTheHillsAndFarAway == xi.questStatus.QUEST_ACCEPTED and\n        npcUtil.tradeHas(trade, xi.item.MOBLIN_HOTROK)\n    then\n        -- 1729 = Moblin Hotrok\n        if player:getMissionStatus(xi.mission.log_id.COP, xi.mission.status.COP.LOUVERANCE) == 14 then\n            if\n                player:hasTitle(xi.title.COMPANION_OF_LOUVERANCE) or\n                player:hasTitle(xi.title.TRUE_COMPANION_OF_LOUVERANCE)\n            then\n                player:startEvent(10, 0, 1729, xi.keyItem.MAP_OF_THE_ULEGUERAND_RANGE, 0, 0, 1, 0)\n                --                                                                      ^ 1 = Remembers you and girl from Tavnazia and asks to TRADE dagger for map\n            else\n                player:startEvent(10, 0, 1729, xi.keyItem.MAP_OF_THE_ULEGUERAND_RANGE, 1, 0, 1, 0)\n                --                                                                ^ 1   ^ 1 = Remembers you and girl from Tavnazia and asks for the dagger\n            end\n        else\n            if\n                player:hasTitle(xi.title.COMPANION_OF_LOUVERANCE) or\n                player:hasTitle(xi.title.TRUE_COMPANION_OF_LOUVERANCE)\n            then\n                player:startEvent(10, 0, 1729, xi.keyItem.MAP_OF_THE_ULEGUERAND_RANGE, 0, 1, 0, 0)\n                --                                                                   ^ 1 = Doesn't recognize you and asks to TRADE dagger for map\n                -- or\n                --                                                                          ^ 1 = Doesn't recognize you and asks to TRADE dagger for map\n            else\n                player:startEvent(10, 0, 1729, xi.keyItem.MAP_OF_THE_ULEGUERAND_RANGE, 1, 0, 0, 0)\n                --                                                                ^ 1 = Doesn't recognize you and asks for the dagger\n            end\n        end\n    end\nend\n\nentity.onTrigger = function(player, npc)\n    local overTheHillsAndFarAway = player:getQuestStatus(xi.questLog.SANDORIA, xi.quest.id.sandoria.OVER_THE_HILLS_AND_FAR_AWAY)\n\n    if overTheHillsAndFarAway == xi.questStatus.QUEST_COMPLETED then\n        player:messageSpecial(ID.text.NOTHING_OUT_OF_ORDINARY)\n    elseif overTheHillsAndFarAway == xi.questStatus.QUEST_ACCEPTED then\n        player:messageSpecial(ID.text.SOMETHING_GLITTERING)\n        player:messageSpecial(ID.text.WHAT_LIES_BENEATH, 0, xi.item.MOBLIN_HOTROK)\n    else\n        player:messageSpecial(ID.text.SOMETHING_GLITTERING_BUT)\n    end\nend\n\nentity.onEventFinish = function(player, csid, option, npc)\n    if\n        csid == 10 and\n        npcUtil.completeQuest(player, xi.questLog.SANDORIA, xi.quest.id.sandoria.OVER_THE_HILLS_AND_FAR_AWAY, {\n            fame = 80,\n            fameArea = xi.fameArea.SANDORIA,\n            keyItem = xi.keyItem.MAP_OF_THE_ULEGUERAND_RANGE,\n            gil = 2000,\n            exp = 2000\n        })\n    then\n        player:confirmTrade()\n    end\nend\n\nreturn entity\n"},["scripts/zones/Upper_Jeuno/npcs/Ajithaam.lua"]={["Path"]="scripts/zones/Upper_Jeuno/npcs/Ajithaam.lua",["SHA256"]="1e58d479dfd842ac8f951cfe3b2cd034f0cda695a377afb79e791cd7be109d31",["Text"]="-----------------------------------\n-- Area: Upper Jeuno\n--  NPC: Ajithaam\n-- !pos -82 0.1 160 244\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrade = function(player, npc, trade)\n    if\n        trade:getGil() == 300 and\n        trade:getItemCount() == 1 and\n        player:getQuestStatus(xi.questLog.JEUNO, xi.quest.id.jeuno.LURE_OF_THE_WILDCAT) == xi.questStatus.QUEST_COMPLETED and\n        player:getCurrentMission(xi.mission.log_id.TOAU) > xi.mission.id.toau.IMMORTAL_SENTRIES\n    then\n        -- Needs a check for at least traded an invitation card to Naja Salaheem\n        player:startEvent(10177)\n    end\nend\n\nentity.onTrigger = function(player, npc)\n    if player:getCurrentMission(xi.mission.log_id.TOAU) >= xi.mission.id.toau.PRESIDENT_SALAHEEM then\n        player:startEvent(10176)\n    end\nend\n\nentity.onEventFinish = function(player, csid, option, npc)\n    if csid == 10177 then\n        player:tradeComplete()\n        xi.teleport.to(player, xi.teleport.id.WHITEGATE)\n    end\nend\n\nreturn entity\n"},["scripts/zones/Upper_Jeuno/npcs/Brutus.lua"]={["Path"]="scripts/zones/Upper_Jeuno/npcs/Brutus.lua",["SHA256"]="3ea2ddeca1058f071b643f35dcee430b4b3293dd7ca4fef18eb399bfe3b75c0c",["Text"]="-----------------------------------\n-- Area: Upper Jeuno\n--  NPC: Brutus\n-- Starts Quest: Chocobo's Wounds, Save My Son, Path of the Beastmaster, Wings of gold, Scattered into Shadow, Chocobo on the Loose!\n-- !pos -55 8 95 244\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrigger = function(player, npc)\n    local wingsOfGold = player:getQuestStatus(xi.questLog.JEUNO, xi.quest.id.jeuno.WINGS_OF_GOLD)\n    local scatteredIntoShadow = player:getQuestStatus(xi.questLog.JEUNO, xi.quest.id.jeuno.SCATTERED_INTO_SHADOW)\n\n    local mLvl = player:getMainLvl()\n\n    -- STANDARD DIALOGS\n    if scatteredIntoShadow == xi.questStatus.QUEST_COMPLETED then\n        player:startEvent(151)\n    elseif wingsOfGold == xi.questStatus.QUEST_COMPLETED then\n        player:startEvent(134)\n    elseif not player:hasCompletedQuest(xi.questLog.JEUNO, xi.quest.id.jeuno.CHOCOBOS_WOUNDS) then\n        player:startEvent(66, mLvl)\n    end\nend\n\nreturn entity\n"},["scripts/zones/Upper_Jeuno/npcs/Mapitoto.lua"]={["Path"]="scripts/zones/Upper_Jeuno/npcs/Mapitoto.lua",["SHA256"]="4c8c793f1caf0a51c8f05e7ecae8363668d63ddb995dd5de2c92a169672c2a5f",["Text"]="-----------------------------------\n-- Area: Upper Jeuno\n--  NPC: Mapitoto\n-- Type: Full Speed Ahead Mount NPC\n-- !pos -54.310 8.200 85.940 244\n-----------------------------------\nlocal ID = zones[xi.zone.UPPER_JEUNO]\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrade = function(player, npc, trade)\n    if\n        player:hasKeyItem(xi.keyItem.TRAINERS_WHISTLE) and\n        trade:getSlotCount() == 1 and\n        -- The Fenrir (10057) and Omega (10067) items and mounts have their own questlines, so they aren't valid trades here\n        not (npcUtil.tradeHasExactly(trade, xi.item.MOUNT_FENRIR) or npcUtil.tradeHasExactly(trade, xi.item.MOUNT_OMEGA))\n    then\n        local item  = trade:getItemId(0)\n        local mount = item - xi.item.MOUNT_TIGER\n        if item == xi.item.CHOCOBO_WHISTLE then\n            -- TODO: The reply to a whistle with no chocobo registered.\n            if not player:getFieldChocobo() then\n                return\n            end\n\n            player:startEvent(10227, xi.item.CHOCOBO_WHISTLE, xi.keyItem.TRAINERS_WHISTLE, 0, xi.keyItem.CHOCOBO_COMPANION)\n            player:setLocalVar('FullSpeedAheadReward', xi.keyItem.CHOCOBO_COMPANION)\n\n            -- The key item comes with the event; its message comes at the end.\n            player:addKeyItem(xi.keyItem.CHOCOBO_COMPANION)\n        elseif item == xi.item.RED_RAPTOR_NOTEBOOK then -- Key Items, Items, and Mount IDs don't line up for 4 mounts starting with Red Raptor\n            player:setLocalVar('FullSpeedAheadReward', xi.keyItem.TIGER_COMPANION + mount + 3)\n            player:startEvent(10227, item, xi.keyItem.TRAINERS_WHISTLE, xi.mount.TIGER + mount + 2)\n        elseif\n            item >= xi.item.GOLDEN_BOMB_NOTEBOOK and\n            item <= xi.item.WIVRE_NOTEBOOK\n        then\n            -- These are all offset by one due to Red Raptor\n            player:setLocalVar('FullSpeedAheadReward', xi.keyItem.TIGER_COMPANION + mount - 1)\n            player:startEvent(10227, item, xi.keyItem.TRAINERS_WHISTLE, xi.mount.TIGER + mount - 2)\n        elseif mount >= xi.mount.CHOCOBO and mount <= xi.mount.MOUNT_MAX then\n            player:setLocalVar('FullSpeedAheadReward', xi.keyItem.TIGER_COMPANION + mount)\n            player:startEvent(10227, item, xi.keyItem.TRAINERS_WHISTLE, xi.mount.TIGER + mount - 1)\n        end\n    end\nend\n\nentity.onTrigger = function(player, npc)\n    local fsaQuest = player:getQuestStatus(xi.questLog.JEUNO, xi.quest.id.jeuno.FULL_SPEED_AHEAD)\n    local fullSpeedAheadStatus = player:getCharVar('[QUEST]FullSpeedAhead')\n\n    if fsaQuest == xi.questStatus.QUEST_COMPLETED then\n        player:startEvent(10226)\n    elseif fullSpeedAheadStatus == 4 then -- Complete\n        player:startEvent(10225, xi.keyItem.TRAINERS_WHISTLE, 15533, ID.npc.MAPITOTO)\n    elseif fsaQuest == xi.questStatus.QUEST_ACCEPTED then -- Retry\n        player:startEvent(10224, 1)\n    elseif\n        player:hasKeyItem(xi.keyItem.CHOCOBO_LICENSE) and\n        player:getMainLvl() >= 20 and\n        player:hasKeyItem(xi.keyItem.MAP_OF_THE_JEUNO_AREA)\n    then\n        player:startEvent(10223, 0, 0, 4)\n    end\nend\n\nentity.onEventFinish = function(player, csid, option, npc)\n    if (csid == 10223 or csid == 10224) and option == 1 then\n        player:addQuest(xi.questLog.JEUNO, xi.quest.id.jeuno.FULL_SPEED_AHEAD)\n        player:setCharVar('[QUEST]FullSpeedAhead', 1) -- Flag to start minigame\n        player:setPos(475, 8.8, -159, 128, 105)\n    elseif csid == 10223 and option == 2 then\n        player:addQuest(xi.questLog.JEUNO, xi.quest.id.jeuno.FULL_SPEED_AHEAD)\n    elseif csid == 10225 then\n        -- Complete quest\n        player:setCharVar('[QUEST]FullSpeedAhead', 0)\n        player:completeQuest(xi.questLog.JEUNO, xi.quest.id.jeuno.FULL_SPEED_AHEAD)\n        player:addFame(xi.fameArea.SANDORIA, 7)\n        player:addFame(xi.fameArea.BASTOK, 7)\n        player:addFame(xi.fameArea.WINDURST, 7)\n        npcUtil.giveKeyItem(player, xi.keyItem.TRAINERS_WHISTLE)\n        npcUtil.giveKeyItem(player, xi.keyItem.RAPTOR_COMPANION)\n    elseif csid == 10227 then\n        local rewardKI = player:getLocalVar('FullSpeedAheadReward')\n        player:setLocalVar('FullSpeedAheadReward', 0)\n        if rewardKI == xi.keyItem.CHOCOBO_COMPANION then\n            -- Nothing is confirmed, so this hands the whistle back.\n            player:confirmTrade()\n            player:messageSpecial(ID.text.KEYITEM_OBTAINED, rewardKI)\n        elseif\n            rewardKI > 0 and\n            player:tradeComplete()\n        then\n            npcUtil.giveKeyItem(player, rewardKI)\n        end\n    end\nend\n\nreturn entity\n"},["scripts/zones/Upper_Jeuno/npcs/Monberaux.lua"]={["Path"]="scripts/zones/Upper_Jeuno/npcs/Monberaux.lua",["SHA256"]="ba42d6799c1796198720b2a653050130606e15f312ff216c3ffa1cc089729393",["Text"]="-----------------------------------\n-- Area: Upper Jeuno\n--  NPC: Monberaux\n-- Starts and Finishes Quest: The Lost Cardian (finish), The kind cardian (start)\n-- Involved in Quests: Save the Clock Tower\n-- Involved in handling his how his alter ego reacts in combat.\n-- !pos -43 0 -1 244\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrade = function(player, npc, trade)\n    local minimumGil = player:getGil() * 0.1\n    local elixirTotal = 2\n\n    local finalElixir = player:getCharVar('finalElixir')\n    local monbAoe = player:getCharVar('monbAoe')\n    local gilAmount = trade:getGil()\n    local elixirType = trade:getItemId(0)\n\n    if minimumGil > 100000 then\n        minimumGil = 100000\n    elseif minimumGil < 10000 then\n        minimumGil = 10000\n    end\n\n    -- Trust Interaction\n    if\n        xi.settings.main.ENABLE_SOA == 1 and\n        player:hasSpell(xi.magic.spell.MONBERAUX)\n    then\n        -- Check trade for elixir/hi-elixir\n        -- TODO: add logic to trade more than 1 at a time, or more than 1 type at a time.\n        if\n            finalElixir < elixirTotal and\n            (trade:hasItemQty(xi.item.ELIXIR, 1) or trade:hasItemQty(xi.item.HI_ELIXIR, 1))\n        then\n            player:startEvent(10243, elixirType, 1, 2, 0, 59615134, 7271819, 4095, 128)\n        elseif\n            (trade:hasItemQty(xi.item.ELIXIR, 1) or\n            trade:hasItemQty(xi.item.HI_ELIXIR, 1)) and\n            finalElixir >= elixirTotal\n        then\n            player:startEvent(10246, elixirType)\n        end\n\n        if\n            gilAmount >= minimumGil and\n            monbAoe == 0\n        then\n            player:startEvent(10238)\n        elseif\n            gilAmount >= minimumGil and\n            monbAoe == 1\n        then\n            player:startEvent(10240)\n        end\n    end\nend\n\nentity.onTrigger = function(player, npc)\n    local theLostCardien = player:getQuestStatus(xi.questLog.JEUNO, xi.quest.id.jeuno.THE_LOST_CARDIAN)\n    local cooksPride = player:getQuestStatus(xi.questLog.JEUNO, xi.quest.id.jeuno.COOKS_PRIDE)\n    local elixirTotal = 2\n    local minimumGil = player:getGil() * 0.1\n\n    if minimumGil > 100000 then\n        minimumGil = 100000\n    elseif minimumGil < 10000 then\n        minimumGil = 10000\n    end\n\n    if not player:hasCompletedUniqueEvent(xi.uniqueEvent.MONBERAUX_INTRODUCTION) then\n        player:startEvent(109)\n    end\n\n    if\n        cooksPride == xi.questStatus.QUEST_COMPLETED and\n        theLostCardien == xi.questStatus.QUEST_AVAILABLE and\n        player:getCharVar('theLostCardianVar') == 2\n    then\n        player:startEvent(33) -- Long CS & Finish Quest \"The Lost Cardian\"\n\n    elseif\n        cooksPride == xi.questStatus.QUEST_COMPLETED and\n        theLostCardien == xi.questStatus.QUEST_AVAILABLE and\n        player:getCharVar('theLostCardianVar') == 3\n    then\n        player:startEvent(34) -- Shot CS & Finish Quest \"The Lost Cardian\"\n\n    elseif\n        theLostCardien == xi.questStatus.QUEST_COMPLETED and\n        player:getQuestStatus(xi.questLog.JEUNO, xi.quest.id.jeuno.THE_KIND_CARDIAN) == xi.questStatus.QUEST_ACCEPTED\n    then\n        player:startEvent(32)\n    end\n\n    -- Trust Interaction\n    if\n        xi.settings.main.ENABLE_SOA == 1 and\n        player:hasSpell(xi.magic.spell.MONBERAUX)\n    then\n        if player:getCharVar('monbAoe') == 0 then\n            player:startEvent(10237, minimumGil, 1, 2964, 3300, 58195966, 3881063, 4480, 128)\n        else\n            player:startEvent(10239)\n        end\n\n        if player:getCharVar('finalElixir') <= elixirTotal then\n            player:startEvent(10241)\n        else\n            player:startEvent(10244)\n        end\n    end\n\n    -- Intentionally split up to not lock the player out of the above interactions while still forcing your introduction to Monberaux to happen.\n    player:startEvent(28)\nend\n\nentity.onEventFinish = function(player, csid, option, npc)\n    local finalElixir = player:getCharVar('finalElixir')\n\n    if\n        (csid == 33 and option == 0) or\n        (csid == 34 and option == 0)\n    then\n        player:addTitle(xi.title.TWOS_COMPANY)\n        player:setCharVar('theLostCardianVar', 0)\n        npcUtil.giveCurrency(player, 'gil', 2100)\n        npcUtil.giveKeyItem(player, xi.keyItem.TWO_OF_SWORDS)\n        player:addFame(xi.fameArea.SANDORIA, 7)\n        player:addFame(xi.fameArea.BASTOK, 7)\n        player:addFame(xi.fameArea.WINDURST, 7)\n        player:completeQuest(xi.questLog.JEUNO, xi.quest.id.jeuno.THE_LOST_CARDIAN)\n        player:addQuest(xi.questLog.JEUNO, xi.quest.id.jeuno.THE_KIND_CARDIAN) -- Start next quest \"THE_KING_CARDIAN\"\n    elseif csid == 33 and option == 1 then\n        player:setCharVar('theLostCardianVar', 3)\n    end\n\n    if csid == 10238 then\n        player:setCharVar('monbAoe', 1, NextJstWeek())\n        player:tradeComplete()\n    end\n\n    if csid == 10243 then\n        player:setCharVar('finalElixir', finalElixir + 1)\n        player:tradeComplete()\n    end\n\n    if csid == 109 then\n        player:setUniqueEvent(xi.uniqueEvent.MONBERAUX_INTRODUCTION)\n    end\nend\n\nreturn entity\n"},["scripts/zones/Upper_Jeuno/npcs/Osker.lua"]={["Path"]="scripts/zones/Upper_Jeuno/npcs/Osker.lua",["SHA256"]="128157b9cda8f70fec46a618fc0ecf10b9583192e2343f407a96a81929264dce",["Text"]="-----------------------------------\n-- Area: Upper Jeuno\n--  NPC: Osker\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrade = function(player, npc, trade)\n    local aNewDawnEvent = player:getCharVar('ANewDawn_Event')\n\n    if\n        trade:hasItemQty(xi.item.PIECE_OF_MAHOGANY_LUMBER, 1) and\n        trade:getItemCount() == 1 and\n        aNewDawnEvent == 3\n    then\n        player:tradeComplete()\n        player:startEvent(148)\n    end\nend\n\nentity.onTrigger = function(player, npc)\n    local aNewDawn = player:getQuestStatus(xi.questLog.JEUNO, xi.quest.id.jeuno.A_NEW_DAWN)\n    local aNewDawnEvent = player:getCharVar('ANewDawn_Event')\n\n    -- A New Dawn\n    if aNewDawn == xi.questStatus.QUEST_ACCEPTED then\n        if aNewDawnEvent == 2 or aNewDawnEvent == 3 then\n            player:startEvent(146)\n        elseif aNewDawnEvent >= 4 then\n            player:startEvent(147)\n        end\n\n    elseif aNewDawn == xi.questStatus.QUEST_COMPLETED then\n        player:startEvent(145)\n    end\nend\n\nentity.onEventFinish = function(player, csid, option, npc)\n    local aNewDawnEvent = player:getCharVar('ANewDawn_Event')\n\n    if csid == 146 then\n        if aNewDawnEvent == 2 then\n            player:setCharVar('ANewDawn_Event', 3)\n        end\n    elseif csid == 148 then\n        npcUtil.giveKeyItem(player, xi.keyItem.TAMERS_WHISTLE)\n        player:setCharVar('ANewDawn_Event', 4)\n    end\nend\n\nreturn entity\n"},["scripts/zones/Vunkerl_Inlet_[S]/npcs/qm4.lua"]={["Path"]="scripts/zones/Vunkerl_Inlet_[S]/npcs/qm4.lua",["SHA256"]="0592a6ecd525c3c53e053e43103d0a74452ff00ccc5467d0b7258a74d5c99235",["Text"]="-----------------------------------\n-- Area: Vunkerl_Inlet_[S]\n--  NPC: qm4 (???)\n-- Involved In Quest: REDEEMING_ROCKS\n-- !pos -412 -29 -45 83\n-----------------------------------\nlocal ID = zones[xi.zone.VUNKERL_INLET_S]\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrigger = function(player, npc)\n    if\n        player:getQuestStatus(xi.questLog.CRYSTAL_WAR, xi.quest.id.crystalWar.REDEEMING_ROCKS) and\n        player:getCharVar('RedeemingRocksProg') == 3\n    then\n        npcUtil.giveKeyItem(player, xi.keyItem.PIECE_OF_KIONITE)\n        player:setCharVar('RedeemingRocksProg', 4)\n    else\n        player:messageSpecial(ID.text.NOTHING_OUT_OF_ORDINARY)\n    end\nend\n\nreturn entity\n"},["scripts/zones/Vunkerl_Inlet_[S]/npcs/qm6.lua"]={["Path"]="scripts/zones/Vunkerl_Inlet_[S]/npcs/qm6.lua",["SHA256"]="ae8c00bb9560ba45a3d80efc6f52cb52f55f818e708ab4e81f07e9dad08b5cb8",["Text"]="-----------------------------------\n-- Area: Vunkerl_Inlet_[S]\n--  NPC: qm6 (???)\n-- Involved In Quest: EVIL_AT_THE_INLET\n-- !pos -636 -51 -454 83\n-----------------------------------\nlocal ID = zones[xi.zone.VUNKERL_INLET_S]\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrigger = function(player, npc)\n    if\n        player:getQuestStatus(xi.questLog.CRYSTAL_WAR, xi.quest.id.crystalWar.EVIL_AT_THE_INLET) == xi.questStatus.QUEST_ACCEPTED and\n        player:hasKeyItem(xi.keyItem.EVIL_WARDING_SEAL)\n    then\n        player:startEvent(112)\n    else\n        player:messageSpecial(ID.text.NOTHING_OUT_OF_ORDINARY)\n    end\nend\n\nentity.onEventFinish = function(player, csid, option, npc)\n    if csid == 112 then\n        player:delKeyItem(xi.keyItem.EVIL_WARDING_SEAL)\n    end\nend\n\nreturn entity\n"},["scripts/zones/West_Sarutabaruta/npcs/Twinkle_Tree.lua"]={["Path"]="scripts/zones/West_Sarutabaruta/npcs/Twinkle_Tree.lua",["SHA256"]="3aebd2875ca33d1c29ac7a4d33888fbb9d004c1009862cffdd7db92dfc003621",["Text"]="-----------------------------------\n-- Area: West Sarutabaruta\n--  NPC: Twinkle Tree\n-- Involved in Quest: To Catch a Falling Star\n--  Note: EventID for Twinkle Tree is unknown. Quest funtions but the full event is not played.\n-- !pos 156.003 -40.753 333.742 115\n-----------------------------------\nlocal ID = zones[xi.zone.WEST_SARUTABARUTA]\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrade = function(player, npc, trade)\n    if\n        player:getQuestStatus(xi.questLog.WINDURST, xi.quest.id.windurst.TO_CATCH_A_FALLING_STAR) == xi.questStatus.QUEST_ACCEPTED and\n        VanadielHour() <= 3\n    then\n        if\n            npcUtil.tradeHas(trade, xi.item.HANDFUL_OF_PUGIL_SCALES) and\n            player:getCharVar('QuestCatchAFallingStar_prog') == 0\n        then\n            player:messageSpecial(ID.text.FROST_DEPOSIT_TWINKLES)\n            player:messageSpecial(ID.text.MELT_BARE_HANDS)\n            if npcUtil.giveItem(player, xi.item.STARFALL_TEAR) then\n                player:confirmTrade()\n                player:setCharVar('QuestCatchAFallingStar_prog', 1)\n            end\n        end\n    end\nend\n\nentity.onTrigger = function(player, npc)\n    if\n        VanadielHour() <= 3 and\n        player:getCharVar('QuestCatchAFallingStar_prog') == 0\n    then\n        player:messageSpecial(ID.text.FROST_DEPOSIT_TWINKLES)\n        player:messageSpecial(ID.text.MELT_BARE_HANDS)\n    else\n        player:messageSpecial(ID.text.NOTHING_OUT_OF_ORDINARY)\n    end\nend\n\nreturn entity\n"},["scripts/zones/Western_Adoulin/npcs/Barenngo.lua"]={["Path"]="scripts/zones/Western_Adoulin/npcs/Barenngo.lua",["SHA256"]="e3c778146035e10e3f72435bd174152df0c56c5a8f0b6833cc73d550f57a11fd",["Text"]="-----------------------------------\n-- Area: Western Adoulin\n--  NPC: Barenngo\n-- Involved with Quests: 'Dont Ever Leaf Me'\n-- !pos -101 3 14 256\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrigger = function(player, npc)\n    local DELM = player:getQuestStatus(xi.questLog.ADOULIN, xi.quest.id.adoulin.DONT_EVER_LEAF_ME)\n\n    if DELM == xi.questStatus.QUEST_ACCEPTED and player:getCharVar('DELM_Barenngo_Branch') < 1 then\n        -- Progresses Quest: 'Dont Ever Leaf Me'\n        player:startEvent(5015)\n    elseif DELM == xi.questStatus.QUEST_ACCEPTED and player:getCharVar('DELM_Barenngo_Branch') < 2 then\n        -- Reminds player of hint for Quest: 'Dont Ever Leaf Me'\n        player:startEvent(5016)\n    end\nend\n\nentity.onEventFinish = function(player, csid, option, npc)\n    if csid == 5015 then\n        -- Progresses Quest: 'Dont Ever Leaf Me'\n        player:setCharVar('DELM_Barenngo_Branch', 1)\n    end\nend\n\nreturn entity\n"},["scripts/zones/Western_Adoulin/npcs/Bilp.lua"]={["Path"]="scripts/zones/Western_Adoulin/npcs/Bilp.lua",["SHA256"]="dcf77120c80e1d94577e79b48cb92b962a14bbfeb038eeec3f26c6bfaca25cfa",["Text"]="-----------------------------------\n-- Area: Western Adoulin\n--  NPC: Bilp\n-- !pos -91 3 0 256\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrigger = function(player, npc)\n    local scaredyCats       = player:getQuestStatus(xi.questLog.ADOULIN, xi.quest.id.adoulin.SCAREDYCATS)\n    local scaredyCatsStatus = player:getCharVar('Scaredycats_Status')\n\n    if scaredyCatsStatus < 1 and scaredyCats == xi.questStatus.QUEST_AVAILABLE then\n        -- Dialogue before seeing the initial walk-in CS with Bilp, Eamonn, and Lhe.\n        player:startEvent(5031)\n    elseif scaredyCatsStatus == 1 then\n        if scaredyCats == xi.questStatus.QUEST_ACCEPTED then\n            -- Reminder for Quest: 'Scaredy-Cats', go to Ceizak Battlegrounds\n            player:startEvent(5025)\n        else\n            -- Starts Quest: 'Scaredy-Cats', after first refusal.\n            player:startEvent(5024)\n        end\n    elseif scaredyCatsStatus == 2 then\n        -- Reminder for Quest: 'Scaredy-Cats', go to Sih Gates.\n        player:startEvent(5026)\n    else\n        -- Dialogue after completeing Quest: 'Scaredy-Cats'\n        player:startEvent(5029)\n    end\nend\n\nentity.onEventFinish = function(player, csid, option, npc)\n    if csid == 5024 and option == 1 then\n        -- Starts Quest: 'Scaredy-Cats', after first refusal.\n        player:setCharVar('Scaredycats_Status', 2)\n        player:addQuest(xi.questLog.ADOULIN, xi.quest.id.adoulin.SCAREDYCATS)\n    end\nend\n\nreturn entity\n"},["scripts/zones/Western_Adoulin/npcs/Chanteillie.lua"]={["Path"]="scripts/zones/Western_Adoulin/npcs/Chanteillie.lua",["SHA256"]="a782eecf5b130fc03965f1ccedf99f830e789bae3f8e7f052c322ff6d84e2cfb",["Text"]="-----------------------------------\n-- Area: Western Adoulin\n--  NPC: Chanteillie\n-- Involved with Quests: 'Do Not Go Into the Light'\n--                       'Vegetable Vegetable Crisis'\n-- !pos 89 0 -75 256\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrade = function(player, npc, trade)\n    local dngitl = player:getQuestStatus(xi.questLog.ADOULIN, xi.quest.id.adoulin.DO_NOT_GO_INTO_THE_LIGHT)\n    local vvc = player:getQuestStatus(xi.questLog.ADOULIN, xi.quest.id.adoulin.VEGETABLE_VEGETABLE_CRISIS)\n\n    -- DO NOT GO INTO THE LIGHT (Urunday Lumber, Damascus Ingot, Fire Crystal)\n    if\n        dngitl == xi.questStatus.QUEST_ACCEPTED and\n        player:getCharVar('DNGITL_Status') == 3 and\n        npcUtil.tradeHas(trade, { 3927, 658, 4096 })\n    then\n        player:startEvent(5076)\n\n    -- VEGETABLE VEGETABLE CRISIS (Urunday Lumber, Midrium Ingot, Raaz Leather)\n    elseif\n        vvc == xi.questStatus.QUEST_ACCEPTED and\n        player:getCharVar('VVC_Status') == 1 and\n        npcUtil.tradeHas(trade, { 3927, 3919, 8708 })\n    then\n        player:startEvent(5089)\n    end\nend\n\nentity.onTrigger = function(player, npc)\n    local dngitl = player:getQuestStatus(xi.questLog.ADOULIN, xi.quest.id.adoulin.DO_NOT_GO_INTO_THE_LIGHT)\n    local vvc = player:getQuestStatus(xi.questLog.ADOULIN, xi.quest.id.adoulin.VEGETABLE_VEGETABLE_CRISIS)\n\n    -- DO NOT GO INTO THE LIGHT\n    if\n        dngitl == xi.questStatus.QUEST_ACCEPTED and\n        player:hasKeyItem(xi.keyItem.INVENTORS_COALITION_PICKAXE)\n    then\n        player:startEvent(5077)\n\n    -- VEGETABLE VEGETABLE CRISIS\n    elseif vvc == xi.questStatus.QUEST_ACCEPTED and player:getCharVar('VVC_Status') == 1 then\n        player:startEvent(5088)\n    end\nend\n\nentity.onEventFinish = function(player, csid, option, npc)\n    -- DO NOT GO INTO THE LIGHT\n    if csid == 5076 then\n        player:confirmTrade()\n        npcUtil.giveKeyItem(player, xi.keyItem.INVENTORS_COALITION_PICKAXE)\n        player:setCharVar('DNGITL_Status', 0)\n\n    -- VEGETABLE VEGETABLE CRISIS\n    elseif csid == 5089 then\n        player:confirmTrade()\n        player:setCharVar('VVC_Status', 2)\n        player:setCharVar('VVC_Gameday_Wait', VanadielUniqueDay())\n    end\nend\n\nreturn entity\n"},["scripts/zones/Western_Adoulin/npcs/Clautaire.lua"]={["Path"]="scripts/zones/Western_Adoulin/npcs/Clautaire.lua",["SHA256"]="b241946631d2965750022796e91b7f52799a5818a4d17e9ca855a3fd66bcaedb",["Text"]="-----------------------------------\n-- Area: Western Adoulin\n--  NPC: Clautaire\n-- Starts, Involved with, and Finishes Quest: 'F.A.I.L.ure Is Not an Option'\n-- !pos 44 4 -159 256\n-----------------------------------\nlocal ID = zones[xi.zone.WESTERN_ADOULIN]\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrigger = function(player, npc)\n    local finao = player:getQuestStatus(xi.questLog.ADOULIN, xi.quest.id.adoulin.FAILURE_IS_NOT_AN_OPTION)\n    if finao == xi.questStatus.QUEST_ACCEPTED then\n        if player:hasKeyItem(xi.keyItem.HUNK_OF_BEDROCK) then\n            -- Finishing Quest: 'F.A.I.L.ure Is Not an Option'\n            player:startEvent(76)\n        else\n            -- Dialgoue during Quest: 'F.A.I.L.ure Is Not an Option'\n            player:startEvent(77)\n        end\n    elseif\n        finao == xi.questStatus.QUEST_AVAILABLE and\n        player:getFameLevel(xi.fameArea.ADOULIN) >= 4 and\n        player:hasKeyItem(xi.keyItem.FAIL_BADGE)\n    then\n        -- Starting Quest: 'F.A.I.L.ure Is Not an Option'\n        player:startEvent(78)\n    end\nend\n\nentity.onEventFinish = function(player, csid, option, npc)\n    if csid == 78 then\n        -- Starting Quest: 'F.A.I.L.ure Is Not an Option'\n        player:addQuest(xi.questLog.ADOULIN, xi.quest.id.adoulin.FAILURE_IS_NOT_AN_OPTION)\n    elseif csid == 76 then\n        -- Finishing Quest: 'F.A.I.L.ure Is Not an Option'\n        player:delKeyItem(xi.keyItem.HUNK_OF_BEDROCK)\n        player:completeQuest(xi.questLog.ADOULIN, xi.quest.id.adoulin.FAILURE_IS_NOT_AN_OPTION)\n        player:addExp(1000 * xi.settings.main.EXP_RATE)\n        player:addCurrency('bayld', 500 * xi.settings.main.BAYLD_RATE)\n        player:messageSpecial(ID.text.BAYLD_OBTAINED, 500 * xi.settings.main.BAYLD_RATE)\n\n        -- TODO: Verify fame value added\n        player:addFame(xi.fameArea.ADOULIN, 30)\n    end\nend\n\nreturn entity\n"},["scripts/zones/Western_Adoulin/npcs/Dewalt.lua"]={["Path"]="scripts/zones/Western_Adoulin/npcs/Dewalt.lua",["SHA256"]="97420ad383d2bc19fd6053842c81af7ae1b5ef49ba7aca7a911e199052baf6e6",["Text"]="-----------------------------------\n-- Area: Western Adoulin\n--  NPC: Dewalt\n-- Involved with Quests: 'Flavors of our Lives', 'Dont Ever Leaf Me'\n--  !pos -23 0 28 256\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrigger = function(player, npc)\n    local DELM = player:getQuestStatus(xi.questLog.ADOULIN, xi.quest.id.adoulin.DONT_EVER_LEAF_ME)\n\n    if DELM == xi.questStatus.QUEST_ACCEPTED and player:getCharVar('DELM_Dewalt_Branch') < 1 then\n        -- Progresses Quest: 'Dont Ever Leaf Me'\n        player:startEvent(5013)\n    elseif DELM == xi.questStatus.QUEST_ACCEPTED and player:getCharVar('DELM_Dewalt_Branch') < 2 then\n        -- Reminds player of hint for Quest: 'Dont Ever Leaf Me'\n        player:startEvent(5014)\n    end\nend\n\nentity.onEventFinish = function(player, csid, option, npc)\n    if csid == 5013 then\n        -- Progresses Quest: 'Dont Ever Leaf Me'\n        player:setCharVar('DELM_Dewalt_Branch', 1)\n    end\nend\n\nreturn entity\n"},["scripts/zones/Western_Adoulin/npcs/Eamonn.lua"]={["Path"]="scripts/zones/Western_Adoulin/npcs/Eamonn.lua",["SHA256"]="ed661bd385c7ef160ec593394f09070ed697e7740453623a843275f5b0bf9f33",["Text"]="-----------------------------------\n-- Area: Western Adoulin\n--  NPC: Eamonn\n-- !pos -91 3 2 256\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrigger = function(player, npc)\n    local scaredyCats = player:getQuestStatus(xi.questLog.ADOULIN, xi.quest.id.adoulin.SCAREDYCATS)\n    local scaredyCatsStatus = player:getCharVar('Scaredycats_Status')\n\n    if scaredyCatsStatus < 1 and scaredyCats == xi.questStatus.QUEST_AVAILABLE then\n        -- Dialogue before seeing the initial walk-in CS with Bilp, Eamonn, and Lhe.\n        player:startEvent(5031)\n    elseif scaredyCatsStatus == 1 then\n        if scaredyCats == xi.questStatus.QUEST_ACCEPTED then\n            -- Reminder for Quest: 'Scaredy-Cats', go to Ceizak Battlegrounds\n            player:startEvent(5025)\n        else\n            -- Starts Quest: 'Scaredy-Cats', after first refusal.\n            player:startEvent(5024)\n        end\n    elseif scaredyCatsStatus == 2 then\n        -- Reminder for Quest: 'Scaredy-Cats', go to Sih Gates.\n        player:startEvent(5027)\n    else\n        -- Dialogue after completeing Quest: 'Scaredy-Cats'\n        player:startEvent(5030)\n    end\nend\n\nentity.onEventFinish = function(player, csid, option, npc)\n    if csid == 5024 and option == 1 then\n        -- Starts Quest: 'Scaredy-Cats', after first refusal.\n        player:setCharVar('Scaredycats_Status', 2)\n        player:addQuest(xi.questLog.ADOULIN, xi.quest.id.adoulin.SCAREDYCATS)\n    end\nend\n\nreturn entity\n"},["scripts/zones/Western_Adoulin/npcs/Flapano.lua"]={["Path"]="scripts/zones/Western_Adoulin/npcs/Flapano.lua",["SHA256"]="e6ca76dd25abf1eeb77398b069dc54a00a6613e1b624ae3de80be04cb4c12903",["Text"]="-----------------------------------\n-- Area: Western Adoulin\n--  NPC: Flapno\n-- !pos 70 0 -13 256\n-----------------------------------\nlocal ID = zones[xi.zone.WESTERN_ADOULIN]\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrade = function(player, npc, trade)\n    local exoticDelicacies = player:getQuestStatus(xi.questLog.ADOULIN, xi.quest.id.adoulin.EXOTIC_DELICACIES)\n\n    -- ALL THE WAY TO THE BANK\n    if\n        player:hasKeyItem(xi.keyItem.TARUTARU_SAUCE_INVOICE) and\n        npcUtil.tradeHas(trade, { { 'gil', 5600 } })\n    then\n        local paidFlapano = utils.mask.getBit(player:getCharVar('ATWTTB_Payments'), 2)\n        if not paidFlapano then\n            player:startEvent(5071)\n        end\n\n    -- EXOTIC DELICACIES\n    elseif exoticDelicacies == xi.questStatus.QUEST_ACCEPTED then\n        if npcUtil.tradeHas(trade, { 3916, 5949, { 5954, 2 } }) then\n            player:startEvent(2861)\n        elseif\n            npcUtil.tradeHas(trade, xi.item.PLATE_OF_BARNACLE_PAELLA) or\n            npcUtil.tradeHas(trade, xi.item.PLATE_OF_FLAPANOS_PAELLA)\n        then\n            player:startEvent(2862)\n        end\n    end\nend\n\nentity.onTrigger = function(player, npc)\n    local theWeatherspoonWar = player:getQuestStatus(xi.questLog.ADOULIN, xi.quest.id.adoulin.THE_WEATHERSPOON_WAR)\n    local exoticDelicacies = player:getQuestStatus(xi.questLog.ADOULIN, xi.quest.id.adoulin.EXOTIC_DELICACIES)\n\n    -- THE WEATHERSPOON WAR\n    if\n        theWeatherspoonWar == xi.questStatus.QUEST_ACCEPTED and\n        player:getCharVar('Weatherspoon_War_Status') == 6\n    then\n        player:startEvent(191)\n\n    -- EXOTIC DELICACIES\n    -- Flapano offers his quest every other time the player talks to him\n    elseif\n        exoticDelicacies ~= xi.questStatus.QUEST_COMPLETED and\n        player:getCharVar('Flapano_Odd_Even') == 0\n    then\n        if exoticDelicacies == xi.questStatus.QUEST_AVAILABLE then\n            player:startEvent(2860)\n        elseif exoticDelicacies == xi.questStatus.QUEST_ACCEPTED then\n            player:startEvent(2863)\n        end\n\n        player:setCharVar('Flapano_Odd_Even', 1)\n\n    -- SHOP\n    else\n        player:showText(npc, ID.text.FLAPANO_SHOP_TEXT)\n        local stock =\n        {\n            { 5943,   125, }, -- Smoked Mackerel\n            { 4415,   124, }, -- Roasted Corn\n            { 4434,  5000, }, -- Mushroom Risotto\n            { 5145,  5600, }, -- Fish and Chips\n            { 4423,   300, }, -- Apple Juice\n            { 4405,   160, }, -- Rice Ball\n            { 5676, 76475, }, -- Mushroom Saute\n        }\n        xi.shop.general(player, stock)\n\n        if exoticDelicacies ~= xi.questStatus.QUEST_COMPLETED then\n            player:setCharVar('Flapano_Odd_Even', 0)\n        end\n    end\nend\n\nentity.onEventFinish = function(player, csid, option, npc)\n    -- ALL THE WAY TO THE BANK\n    if csid == 5071 then\n        player:confirmTrade()\n        player:setCharVar('ATWTTB_Payments', utils.mask.setBit(player:getCharVar('ATWTTB_Payments'), 2, true))\n        if utils.mask.isFull(player:getCharVar('ATWTTB_Payments'), 5) then\n            npcUtil.giveKeyItem(player, xi.keyItem.TARUTARU_SAUCE_RECEIPT)\n        end\n\n    -- EXOTIC DELICACIES\n    elseif csid == 2860 and option == 1 then\n        player:addQuest(xi.questLog.ADOULIN, xi.quest.id.adoulin.EXOTIC_DELICACIES)\n    elseif csid == 2861 then\n        if npcUtil.completeQuest(player, xi.questLog.ADOULIN, xi.quest.id.adoulin.EXOTIC_DELICACIES, { bayld = 500, item = xi.item.PLATE_OF_FLAPANOS_PAELLA, exp = 1000 }) then\n            player:confirmTrade()\n            player:setCharVar('Flapano_Odd_Even', 0)\n        end\n    end\nend\n\nreturn entity\n"},["scripts/zones/Western_Adoulin/npcs/Gontrain.lua"]={["Path"]="scripts/zones/Western_Adoulin/npcs/Gontrain.lua",["SHA256"]="15efd8759204bc2e7ed549786f36f36e304b748403a0f4209ec2e61c05c3b6fa",["Text"]="-----------------------------------\n-- Area: Western Adoulin\n--  NPC: Gontrain\n-- Involved with Quest: 'Raptor Rapture'\n-- !pos 13 0 -143 256\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrigger = function(player, npc)\n    local raptorRapture = player:getQuestStatus(xi.questLog.ADOULIN, xi.quest.id.adoulin.RAPTOR_RAPTURE)\n\n    if\n        raptorRapture == xi.questStatus.QUEST_ACCEPTED and\n        player:getCharVar('Raptor_Rapture_Status') == 4\n    then\n        -- Progresses Quest: 'Raptor Rapture', speaking to Ilney.\n        player:startEvent(5034)\n    end\nend\n\nentity.onEventFinish = function(player, csid, option, npc)\n    if csid == 5034 then\n        -- Progresses Quest: 'Raptor Rapture', spoke to Ilney.\n        player:setCharVar('Raptor_Rapture_Status', 5)\n    end\nend\n\nreturn entity\n"},["scripts/zones/Western_Adoulin/npcs/Grevan.lua"]={["Path"]="scripts/zones/Western_Adoulin/npcs/Grevan.lua",["SHA256"]="38a75f5947f19de6192cc2fac36933d1b1d1bd0f3fa22f284b85466f6672ed00",["Text"]="-----------------------------------\n-- Area: Western Adoulin\n--  NPC: Grevan\n-- Involved With Quest: 'Order Up'\n-- !pos 50 0 6 256\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrigger = function(player, npc)\n    local orderUp = player:getQuestStatus(xi.questLog.ADOULIN, xi.quest.id.adoulin.ORDER_UP)\n    local orderGrevan = utils.mask.getBit(player:getCharVar('Order_Up_NPCs'), 10)\n\n    if orderUp == xi.questStatus.QUEST_ACCEPTED and not orderGrevan then\n        -- Progresses Quest: 'Order Up'\n        player:startEvent(69)\n    else\n        if player:getQuestStatus(xi.questLog.ADOULIN, xi.quest.id.adoulin.HYPOCRITICAL_OATH) == xi.questStatus.QUEST_COMPLETED then\n            if player:getQuestStatus(xi.questLog.ADOULIN, xi.quest.id.adoulin.NOTSOCLEAN_BILL) == xi.questStatus.QUEST_COMPLETED then\n                -- Standard dialogue after stamping out plague in Svenja quest line\n                player:startEvent(188)\n            else\n                -- Standard dialogue before stamping out plague in Svenja quest line\n                player:startEvent(171)\n            end\n        end\n    end\nend\n\nentity.onEventFinish = function(player, csid, option, npc)\n    if csid == 69 then\n        -- Progresses Quest: 'Order Up'\n        player:setCharVar('Order_Up_NPCs', utils.mask.setBit(player:getCharVar('Order_Up_NPCs'), 10, true))\n    end\nend\n\nreturn entity\n"},["scripts/zones/Western_Adoulin/npcs/Jorin.lua"]={["Path"]="scripts/zones/Western_Adoulin/npcs/Jorin.lua",["SHA256"]="23aba200f3eaff26fe36a573c1d0f3ca2f221ae0442c6919abdb1e6aa4bc376c",["Text"]="-----------------------------------\n-- Area: Western Adoulin\n--  NPC: Jorin\n-- Starts, Involved with, and Finishes Quest: 'The Old Man and the Harpoon'\n-- !pos 92 32 152 256\n-----------------------------------\nlocal ID = zones[xi.zone.WESTERN_ADOULIN]\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrigger = function(player, npc)\n    local tomath = player:getQuestStatus(xi.questLog.ADOULIN, xi.quest.id.adoulin.THE_OLD_MAN_AND_THE_HARPOON)\n\n    if tomath == xi.questStatus.QUEST_ACCEPTED then\n        if player:hasKeyItem(xi.keyItem.EXTRAVAGANT_HARPOON) then\n            -- Finishing Quest: 'The Old Man and the Harpoon'\n            player:startEvent(2542)\n        else\n            -- Dialgoue during Quest: 'The Old Man and the Harpoon'\n            player:startEvent(2541)\n        end\n    elseif tomath == xi.questStatus.QUEST_AVAILABLE then\n        -- Starts Quest: 'The Old Man and the Harpoon'\n        player:startEvent(2540)\n    end\nend\n\nentity.onEventFinish = function(player, csid, option, npc)\n    if csid == 2540 then\n        -- Starting Quest: 'The Old Man and the Harpoon'\n        player:addQuest(xi.questLog.ADOULIN, xi.quest.id.adoulin.THE_OLD_MAN_AND_THE_HARPOON)\n        npcUtil.giveKeyItem(player, xi.keyItem.BROKEN_HARPOON)\n    elseif csid == 2542 then\n        -- Finishing Quest: 'The Old Man and the Harpoon'\n        player:completeQuest(xi.questLog.ADOULIN, xi.quest.id.adoulin.THE_OLD_MAN_AND_THE_HARPOON)\n        player:addExp(500 * xi.settings.main.EXP_RATE)\n        player:addCurrency('bayld', 300 * xi.settings.main.BAYLD_RATE)\n        player:messageSpecial(ID.text.BAYLD_OBTAINED, 300 * xi.settings.main.BAYLD_RATE)\n        player:delKeyItem(xi.keyItem.EXTRAVAGANT_HARPOON)\n\n        -- TODO: Verify fame value added\n        player:addFame(xi.fameArea.ADOULIN, 30)\n    end\nend\n\nreturn entity\n"},["scripts/zones/Western_Adoulin/npcs/Marjoirelle.lua"]={["Path"]="scripts/zones/Western_Adoulin/npcs/Marjoirelle.lua",["SHA256"]="2a61639372dce383ece27c718d151cac087a34358f7825f785de0cf16310ae1f",["Text"]="-----------------------------------\n-- Area: Western Adoulin\n--  NPC: Majoirelle\n--  Involved With Quest: 'Order Up'\n-- !pos 127 4 -81 256\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrigger = function(player, npc)\n    local orderUp = player:getQuestStatus(xi.questLog.ADOULIN, xi.quest.id.adoulin.ORDER_UP)\n    local orderMarjoirelle = utils.mask.getBit(player:getCharVar('Order_Up_NPCs'), 8)\n\n    if orderUp == xi.questStatus.QUEST_ACCEPTED and not orderMarjoirelle then\n        -- Progresses Quest: 'Order Up'\n        player:startEvent(68)\n    end\nend\n\nentity.onEventFinish = function(player, csid, option, npc)\n    if csid == 68 then\n        -- Progresses Quest: 'Order Up'\n        player:setCharVar('Order_Up_NPCs', utils.mask.setBit(player:getCharVar('Order_Up_NPCs'), 8, true))\n    end\nend\n\nreturn entity\n"},["scripts/zones/Western_Adoulin/npcs/Mastan.lua"]={["Path"]="scripts/zones/Western_Adoulin/npcs/Mastan.lua",["SHA256"]="b094d14baa4d2a3ead77a980e866e293b4dad88ec61fbb3ed39437f32b1e8cb4",["Text"]="-----------------------------------\n-- Area: Western Adoulin\n--  NPC: Mastan\n--  Involved with Quests: 'Order Up'\n--                        'The Curious Case of Melvien'\n-- !pos -9 0 67 256\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrigger = function(player, npc)\n    local tccom = player:getQuestStatus(xi.questLog.ADOULIN, xi.quest.id.adoulin.THE_CURIOUS_CASE_OF_MELVIEN)\n    local tccomNeedKI = player:hasKeyItem(xi.keyItem.MELVIENS_TURN) and not player:hasKeyItem(xi.keyItem.MELVIENS_DEATH)\n    local orderUp = player:getQuestStatus(xi.questLog.ADOULIN, xi.quest.id.adoulin.ORDER_UP)\n    local orderMastan = utils.mask.getBit(player:getCharVar('Order_Up_NPCs'), 11)\n\n    if orderUp == xi.questStatus.QUEST_ACCEPTED and not orderMastan then\n        -- Progresses Quest: 'Order Up'\n        player:startEvent(70)\n    elseif tccom == xi.questStatus.QUEST_ACCEPTED and tccomNeedKI then\n        -- Progresses Quest: 'The Curious Case of Melvien'\n        player:startEvent(184)\n    end\nend\n\nentity.onEventFinish = function(player, csid, option, npc)\n    if csid == 70 then\n        player:setCharVar('Order_Up_NPCs', utils.mask.setBit(player:getCharVar('Order_Up_NPCs'), 11, true))\n    elseif csid == 184 and option == 1 then\n        npcUtil.giveKeyItem(player, xi.keyItem.MELVIENS_DEATH)\n    end\nend\n\nreturn entity\n"},["scripts/zones/Western_Adoulin/npcs/Merleg.lua"]={["Path"]="scripts/zones/Western_Adoulin/npcs/Merleg.lua",["SHA256"]="3bef0c70182b3f77c66e4ec509cfb6b9a9efe941d91e0ba914deb5873f86c4cc",["Text"]="-----------------------------------\n-- Area: Western Adoulin\n--  NPC: Merleg\n-- Starts, Involved with, and Finishes Quest: 'A Pioneers Best (Imaginary) Friend'\n-- !pos 34 0 -131 256\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrigger = function(player, npc)\n    local apbif = player:getQuestStatus(xi.questLog.ADOULIN, xi.quest.id.adoulin.A_PIONEERS_BEST_IMAGINARY_FRIEND)\n    if apbif == xi.questStatus.QUEST_ACCEPTED then\n        if player:hasStatusEffect(xi.effect.IONIS) then\n            -- Finishing Quest: 'A Pioneers Best (Imaginary) Friend'\n            player:startEvent(2522)\n        else\n            -- Dialgoue during Quest: 'A Pioneers Best (Imaginary) Friend'\n            player:startEvent(2521)\n        end\n    elseif apbif == xi.questStatus.QUEST_AVAILABLE then\n        player:startEvent(2520)\n    end\nend\n\nentity.onEventFinish = function(player, csid, option, npc)\n    if csid == 2520 then\n        -- Starting Quest: 'A Pioneers Best (Imaginary) Friend'\n        player:addQuest(xi.questLog.ADOULIN, xi.quest.id.adoulin.A_PIONEERS_BEST_IMAGINARY_FRIEND)\n        if player:hasStatusEffect(xi.effect.IONIS) then\n            -- Finishes quest if Ionis is already active\n            player:startEvent(2522)\n        end\n    elseif csid == 2522 then\n        -- Finishing Quest: 'A Pioneers Best (Imaginary) Friend'\n        player:completeQuest(xi.questLog.ADOULIN, xi.quest.id.adoulin.A_PIONEERS_BEST_IMAGINARY_FRIEND)\n        player:addExp(500 * xi.settings.main.EXP_RATE)\n        npcUtil.giveCurrency(player, 'bayld', 200)\n        npcUtil.giveKeyItem(player, xi.keyItem.FAIL_BADGE)\n\n        -- TODO: Verify fame value added\n        player:addFame(xi.fameArea.ADOULIN, 30)\n    end\nend\n\nreturn entity\n"}};
